import { copyToolDiscoveryMetadata } from "./discovery-metadata.js";
import { hasTrustedPlatformSource } from "./platform-source-provenance.js";
import { markTrustedHostToolProvenance } from "./host-tool-provenance.js";
import { dynamicTool } from "./factory.js";
import { markRemoteToolProvenance } from "./remote-tool-provenance.js";
import { INVALID_ARGUMENT } from "../errors/index.js";
import { JSON_VALUE_MAX_SERIALIZED_BYTES, snapshotBoundedJsonValue, } from "../schemas/json-value.js";
function toToolInputRecord(input) {
    // One string, such as base64 attachment content, may use the whole input
    // bound; each source still applies its own request limits.
    const snapshot = snapshotBoundedJsonValue(input, JSON_VALUE_MAX_SERIALIZED_BYTES);
    if (!snapshot.success ||
        typeof snapshot.value !== "object" ||
        snapshot.value === null ||
        Array.isArray(snapshot.value)) {
        throw INVALID_ARGUMENT.create({
            detail: "Remote tool input must be a bounded JSON object",
        });
    }
    return snapshot.value;
}
/** Create tools from remote definitions. */
export function createToolsFromRemoteDefinitions(source, definitions, options = {}) {
    const entries = [];
    const materializedNames = new Set();
    for (const definition of definitions) {
        const hasAlias = options.toolNameAliases !== undefined &&
            Object.hasOwn(options.toolNameAliases, definition.name);
        const toolName = hasAlias ? options.toolNameAliases[definition.name] : definition.name;
        if (typeof toolName !== "string" || toolName.length === 0) {
            throw INVALID_ARGUMENT.create({
                detail: `Remote tool "${definition.name}" must have a non-empty materialized name`,
            });
        }
        if (materializedNames.has(toolName)) {
            throw INVALID_ARGUMENT.create({
                detail: `Remote definitions contain duplicate materialized tool name "${toolName}"`,
            });
        }
        materializedNames.add(toolName);
        const remoteTool = markRemoteToolProvenance(dynamicTool({
            id: toolName,
            description: definition.description,
            // The remote JSON Schema is provider metadata; the remote server owns
            // semantic validation. Keep the local admission path data-only so a
            // caller-controlled accessor cannot run inside a schema adapter.
            inputSchema: {},
            inputSchemaJson: definition.parameters,
            mcp: {
                title: definition.title,
                annotations: definition.annotations,
            },
            execute: async (input, context) => await source.executeTool(definition.name, toToolInputRecord(input), context),
        }), definition.name);
        copyToolDiscoveryMetadata(definition, remoteTool);
        entries.push([
            toolName,
            hasTrustedPlatformSource(source) ? markTrustedHostToolProvenance(remoteTool) : remoteTool,
        ]);
    }
    return Object.fromEntries(entries);
}
/** Loads remote tools from source. */
export async function loadRemoteToolsFromSource(source, options = {}) {
    const definitions = await source.listTools(options.context);
    return createToolsFromRemoteDefinitions(source, definitions, {
        toolNameAliases: options.toolNameAliases,
    });
}
